export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    {
      let redirect = false;
      const target = new URL(url.toString());
      if (target.hostname === WWW_HOST) { target.hostname = new URL(CANONICAL_ORIGIN).hostname; redirect = true; }
      if (target.protocol === "http:") { target.protocol = "https:"; redirect = true; }
      if (target.pathname.length > 1 && target.pathname.endsWith("/")) { target.pathname = target.pathname.replace(/\/+$/, "") || "/"; redirect = true; }
      if (redirect) return Response.redirect(target.toString(), 301);
    }
    const path = url.pathname === "/" ? "/index.html" : url.pathname;

    if (request.method === "POST" && url.pathname === "/login") {
      const form = await request.formData();
      const email = field(form, "email");
      const password = String(form.get("password") || "");
      if (!isEmail(email) || !password.trim()) {
        return text(400, "Please enter your email and password.");
      }
      return Response.redirect(new URL("/login?notice=1", request.url), 303);
    }

    if (request.method === "POST" && (url.pathname === "/contact" || url.pathname === "/join")) {
      const form = await request.formData();
      if (field(form, "company_fax")) {
        const next = url.pathname === "/join" ? "/received?for=join" : "/received?for=contact";
        return Response.redirect(new URL(next, request.url), 303);
      }
      try {
        if (url.pathname === "/contact") {
          const name = field(form, "name");
          const email = field(form, "email");
          const message = String(form.get("message") || "").trim();
          if (!name || !isEmail(email) || !message) {
            return text(400, "Please fill in your name, a valid email, and a message.");
          }
          await sendMail(
            env,
            email,
            "Business Leaders contact",
            "New contact message from the Walton County Business Leaders website.\n\nName: " + name + "\nEmail: " + email + "\n\nMessage:\n" + message
          );
          return Response.redirect(new URL("/received?for=contact", request.url), 303);
        }

        const name = field(form, "name");
        const email = field(form, "email");
        const phone = field(form, "phone");
        const company = field(form, "company");
        const role = field(form, "role");
        const industry = field(form, "industry");
        const years = field(form, "years_in_walton");
        const website = field(form, "website");
        const about = String(form.get("about") || "").trim();
        if (!name || !isEmail(email) || !phone || !company || !role || !industry || !years) {
          return text(400, "Please fill in all required fields with a valid email.");
        }
        await sendMail(
          env,
          email,
          "Business Leaders membership application",
          [
            "New membership application from the Walton County Business Leaders website.",
            "",
            "Full name: " + name,
            "Email: " + email,
            "Phone: " + phone,
            "Business or company: " + company,
            "Role: " + role,
            "Industry or type of work: " + industry,
            "How long in Walton County: " + years,
            "Business website: " + (website || "(not provided)"),
            "",
            "About:",
            about || "(not provided)",
          ].join("\n")
        );
        return Response.redirect(new URL("/received?for=join", request.url), 303);
      } catch (err) {
        return text(500, "We could not send that just now. Please try again in a moment.");
      }
    }

    if (request.method !== "GET" && request.method !== "HEAD") {
      return text(405, "Method not allowed");
    }

    if (path === "/robots.txt") {
      return new Response(request.method === "HEAD" ? null : ROBOTS_TXT, { headers: { ...HEADERS, "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "public, max-age=3600" } });
    }
    if (path === "/sitemap.xml") {
      return new Response(request.method === "HEAD" ? null : SITEMAP_XML, { headers: { ...HEADERS, "Content-Type": "application/xml; charset=utf-8", "Cache-Control": "public, max-age=3600" } });
    }
    if (path === "/index.html") return html(request.method === "HEAD" ? null : HOME);
    if (path === "/join" || path === "/join.html") return html(request.method === "HEAD" ? null : JOIN);
    if (path === "/login" || path === "/login.html") {
      const notice = url.searchParams.get("notice") === "1"
        ? '<p class="login-notice" role="status">No approved member account matches that email yet.</p>'
        : "";
      const page = LOGIN.replace("<!--LOGIN_NOTICE-->", notice);
      return html(request.method === "HEAD" ? null : page);
    }
    if (path === "/received") {
      const page = url.searchParams.get("for") === "join" ? THANKS_JOIN : THANKS_CONTACT;
      return html(request.method === "HEAD" ? null : page);
    }

    const allowed = path === "/styles.css" || path === "/robots.txt" || path.startsWith("/fonts/") || path.endsWith(".png") || path.endsWith(".jpg") || path.endsWith(".jpeg");
    if (!allowed || path.includes("..")) {
      return text(404, "Not found");
    }

    const upstream = await fetch(ORIGIN + path);
    if (!upstream.ok) {
      return text(404, "Not found");
    }
    const ext = path.slice(path.lastIndexOf("."));
    const type = TYPES[ext] || "application/octet-stream";
    return new Response(request.method === "HEAD" ? null : upstream.body, {
      headers: { ...HEADERS, "Content-Type": type, "Cache-Control": "public, max-age=300" },
    });
  },
};
